mapper.select:
WHERE 1=1
AND U.COMPANY_ID = #{companyId}
AND U.REG_DATE BETWEEN #{sDate} AND #{eDate}
AND C.COMPANY_NAME LIKE CONCAT('%',#{searchValue},'%') AND O.ORG_NAME LIKE CONCAT('%',#{searchValue},'%') AND U.USER_NAME LIKE CONCAT('%',#{searchValue},'%') AND (C.COMPANY_NAME LIKE CONCAT('%',#{searchValue},'%') OR O.ORG_NAME LIKE CONCAT('%',#{searchValue},'%') OR U.USER_NAME LIKE CONCAT('%',#{searchValue},'%'))
ORDER BY U.REG_DATE DESC

mapper.update:
UPDATE TBL_USER_INFO
SET USER_NAME = #{userName}
, USER_PW = #{userPw}
, COMPANY_ID = #{companyId}
, ORG_ID = #{orgId}
, USER_PHONE = #{userPhone}
, USER_PHONE2 = #{userPhone2}
, AUTH_ID = #{authId}
, UPDATED_AT = CURDATE()
WHERE USER_ID = #{userId}

	AND COMPANY_ID = #{scopeCompanyId}

